package org.joda.time.base;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.time.Chronology;
import org.joda.time.DateTimeUtils;
import org.joda.time.DurationField;
import org.joda.time.DurationFieldType;
import org.joda.time.DurationType;
import org.joda.time.MutablePeriod;
import org.joda.time.Period;
import org.joda.time.PeriodType;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.ReadablePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BaseSingleFieldPeriod_equals_TriageGen1Test {

    /**
     * Concrete implementation for testing since BaseSingleFieldPeriod is protected 
     * and abstract.
     */
    private static class TestPeriod extends BaseSingleFieldPeriod {
        private final PeriodType periodType;
        private final DurationType durationType;

        TestPeriod(int value, PeriodType periodType, DurationType durationType) {
            super(value);
            this.periodType = periodType;
            this.durationType = durationType;
        }

        @Override
        public PeriodType getPeriodType() {
            return periodType;
        }

        @Override
        public DurationFieldType getFieldType() {
            return durationType;
        }

        @Override
        public DurationFieldType getFieldType(int index) {
            return durationType;
        }

        @Override
        public int size() {
            return 1;
        }

        @Override
        public boolean isSupported(DurationFieldType type) {
            return type.equals(durationType);
        }

        @Override
        public int get(DurationFieldType type) {
            return getValue();
        }

        @Override
        public int getValue(int index) {
            return getValue();
        }

        @Override
        public Period toPeriod() {
            return null; // Not needed for equals test
        }

        @Override
        public MutablePeriod toMutablePeriod() {
            return null; // Not needed for equals test
        }
    }

    @Test
    public void testEquals_Identity() {
        TestPeriod period = new TestPeriod(10, PeriodType.standard(), DurationType.standard());
        // Covers: if (this == period) return true;
        assertTrue(period.equals(period));
    }

    @Test
    public void testEquals_Null() {
        TestPeriod period = new TestPeriod(10, PeriodType.standard(), DurationType.standard());
        // Covers: if (period instanceof ReadablePeriod == false) return false;
        assertFalse(period.equals(null));
    }

    @Test
    public void testEquals_WrongType() {
        TestPeriod period = new TestPeriod(10, PeriodType.standard(), DurationType.standard());
        String notAPeriod = "not a period";
        // Covers: if (period instanceof ReadablePeriod == false) return false;
        assertFalse(period.equals(notAPeriod));
    }

    @Test
    public void testEquals_SameValueAndType() {
        TestPeriod period1 = new TestPeriod(10, PeriodType.standard(), DurationType.standard());
        TestPeriod period2 = new TestPeriod(10, PeriodType.standard(), DurationType.standard());
        // Covers: return (other.getPeriodType() == getPeriodType() && other.getValue(0) == getValue());
        assertTrue(period1.equals(period2));
    }

    @Test
    public void testEquals_DifferentValue() {
        TestPeriod period1 = new TestPeriod(10, PeriodType.standard(), DurationType.standard());
        TestPeriod period2 = new TestPeriod(20, PeriodType.standard(), DurationType.standard());
        // Covers: branch where value check fails
        assertFalse(period1.equals(period2));
    }

    @Test
    public void testEquals_DifferentType() {
        TestPeriod period1 = new TestPeriod(10, PeriodType.standard(), DurationType.standard());
        // Mocking a different PeriodType
        ReadablePeriod other = mock(ReadablePeriod.class);
        when(other.getPeriodType()).thenReturn(PeriodType.dayPeriod());
        when(other.getValue(0)).thenReturn(10);

        // Covers: branch where type check fails
        assertFalse(period1.equals(other));
    }

    @Test
    public void testEquals_DifferentTypeWithSameValue() {
        TestPeriod period1 = new TestPeriod(10, PeriodType.standard(), DurationType.standard());
        ReadablePeriod other = mock(ReadablePeriod.class);
        when(other.getPeriodType()).thenReturn(PeriodType.dayPeriod());
        when(other.getValue(0)).thenReturn(10);

        assertFalse(period1.equals(other));
    }
}
